/*
 * Dark Chaos - hunter pet family abilities that need code
 * =======================================================
 *
 * The post-WotLK pet families are data: their skill lines and the downported family specials are
 * in Custom/Custom feature SQLs/worlddb/Pets/ (generated by tools/gen_pet_family_abilities.py).
 *
 * This file covers the one special that data cannot express:
 *  - Stone Armor (160049, Quilen): "When falling below 40% health, the Quilen's skin will change to
 *    stone". The passive procs Stone Armor (160048) on damage taken and spell_proc holds its 120 sec
 *    cooldown, but a proc entry has no health condition, so the threshold (effect 1) is checked here.
 */

#include "ScriptMgr.h"
#include "SpellInfo.h"
#include "SpellScript.h"
#include "SpellScriptLoader.h"
#include "Unit.h"

enum HunterPetAbilitySpells
{
    SPELL_PET_STONE_ARMOR_EFFECT = 160048
};

// 160049 - Stone Armor
class spell_pet_quilen_stone_armor : public AuraScript
{
    PrepareAuraScript(spell_pet_quilen_stone_armor);

    bool Validate(SpellInfo const* /*spellInfo*/) override
    {
        return ValidateSpellInfo({ SPELL_PET_STONE_ARMOR_EFFECT });
    }

    bool CheckProc(ProcEventInfo& eventInfo)
    {
        DamageInfo* damageInfo = eventInfo.GetDamageInfo();
        if (!damageInfo || !damageInfo->GetDamage())
            return false;

        // effect 1 holds the health threshold ("When falling below $s2% health")
        int32 const threshold = GetSpellInfo()->Effects[EFFECT_1].CalcValue();
        return GetTarget()->HealthBelowPctDamaged(threshold, damageInfo->GetDamage());
    }

    void Register() override
    {
        DoCheckProc += AuraCheckProcFn(spell_pet_quilen_stone_armor::CheckProc);
    }
};

void AddSC_dc_hunter_pet_abilities()
{
    RegisterSpellScript(spell_pet_quilen_stone_armor);
}
